#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main() {
    int v, e, src;
    if (scanf("%d %d %d", &v, &e, &src) != 3) return 0;
    long long dist[10005];
    for (int i = 0; i < v; i++) dist[i] = LLONG_MAX;
    dist[src] = 0;

    int *u = malloc(e * sizeof(int));
    int *to = malloc(e * sizeof(int));
    int *w = malloc(e * sizeof(int));
    for (int i = 0; i < e; i++) scanf("%d %d %d", &u[i], &to[i], &w[i]);

    for (int i = 0; i < v - 1; i++) {
        for (int j = 0; j < e; j++) {
            if (dist[u[j]] != LLONG_MAX && dist[u[j]] + w[j] < dist[to[j]]) {
                dist[to[j]] = dist[u[j]] + w[j];
            }
        }
    }
    for (int i = 0; i < v; i++) {
        if (dist[i] == LLONG_MAX) printf("-1%s", i == v - 1 ? "\n" : " ");
        else printf("%lld%s", dist[i], i == v - 1 ? "\n" : " ");
    }
    free(u); free(to); free(w);
    return 0;
}
